2	import { runScenario, type Scenario } from "./claim-office.js";
3	
4	// The scenario arrives on stdin as a single JSON document, read to EOF by file
5	// descriptor rather than streamed — there is nothing to do until all of it has
6	// arrived.
7	const STDIN_FILE_DESCRIPTOR = 0;
8	
9	// A rejected scenario yields an explanation on stderr and no results at all:
10	// the office does not report a partial settlement. Since the whole scenario is
11	// run before anything is written, a rejection anywhere leaves stdout untouched.
12	try {
13	  const scenario = JSON.parse(
14	    readFileSync(STDIN_FILE_DESCRIPTOR, "utf8"),
15	  ) as Scenario;
16	
17	  process.stdout.write(`${JSON.stringify(runScenario(scenario))}\n`);
18	} catch (error) {
19	  process.stderr.write(`${(error as Error).message}\n`);
20	  process.exit(1);
21	}
